UPDATE university_scholarships SET scholarship_name = 'KTH Scholarship', availability_status = 'available', funding_type = 'Full Tuition Waiver', max_scholarship = 'Full tuition fee of a one- or two-year master''s programme (both years, subject to satisfactory first-year results); living costs not included', covers_tuition = true, covers_living_expenses = false, valued_aspect = 'Academic excellence + sustainable-development motivation (9% of admitted applicants nominated in 2026)', eligibility_notes = 'Fee-paying master''s applicants only, and KTH must be your FIRST priority at universityadmissions.se (second/third/fourth priorities cannot carry the scholarship) with the application fee paid. Two steps: programme application by 15 Jan 2027 (documents by 1 Feb 2027), then the scholarship form on the KTH page in the same round. Not for joint Erasmus+/EIT programmes (see the KTH Joint Programme Scholarship).', official_url = 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-scholarship-1.72827', source_url = 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-scholarship-1.72827', verification_status = 'verified', last_verified_at = now() WHERE id = 83;

UPDATE university_scholarships SET scholarship_name = 'Chalmers Master''s Scholarships for Fee-Paying Students (Avancez, IPOET, Adlerbert, US Friends)', availability_status = 'available', funding_type = 'Tuition Waiver', max_scholarship = 'Avancez/IPOET: 75% tuition reduction (up to 85% level in year 2 for 60-credit high-CGPA students); further named schemes (Adlerbert, US Friends) in the same portal application', covers_tuition = true, covers_living_expenses = false, valued_aspect = 'Relative merit value; rank a Chalmers programme as priority 1', eligibility_notes = 'Prospective fee-paying master''s students only. Apply to the programme at universityadmissions.se first (8-digit application number needed), then in the Chalmers scholarship portal (2027 round: late Nov 2026 to the mid-January programme deadline; offers March-early May). One form can cover several schemes. Retention needs 30 passed credits in the first three study periods; scholarships are fee reductions only, never living-cost support.', official_url = 'https://www.chalmers.se/en/education/application-and-admission/scholarships-for-fee-paying-students/', source_url = 'https://www.chalmers.se/en/education/application-and-admission/scholarships-for-fee-paying-students/', verification_status = 'verified', last_verified_at = now() WHERE id = 107;
